result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_gzip_bench.py", "content": """"Pytest suite for the gzip whole-blob vs streaming benchmark."""

import gzip
import hashlib
import tracemalloc
from pathlib import Path

import pytest

import gzip_bench


@pytest.fixture(scope="module")
def source(tmp_path_factory) -> Path:
    path = tmp_path_factory.mktemp("src") / "source_40mb.txt"
    return gzip_bench.generate_source(path)


@pytest.fixture(scope="module")
def source_hash(source: Path) -> str:
    return gzip_bench.sha256_of(source)


@pytest.fixture(scope="module")
def results(source: Path):
    whole = gzip_bench.compress_wholeblob(source, Path("out_wholeblob.gz"))
    stream = gzip_bench.compress_streaming(source, Path("out_streaming.gz"))
    return {"whole": whole, "stream": stream}


@pytest.fixture(scope="module")
def roundtrip_hashes(results) -> dict[str, str]:
    hashes = {}
    for key, m in results.items():
        out = Path(f"rt_{key}.bin")
        gzip_bench.decompress_to(m.output_path, out)
        hashes[key] = hashlib.sha256(out.read_bytes()).hexdigest()
        out.unlink()
    return hashes


def _measure_peak(fn):
    tracemalloc.start()
    fn()
    _, peak = tracemalloc.get_traced_memory()
    tracemalloc.stop()
    return peak


# ---------------------------------------------------------------- validity

@pytest.mark.parametrize("key", ["whole", "stream"])
def test_output_is_valid_gzip(results, roundtrip_hashes, source_hash, key):
    """Each .gz must be decompressible and yield exactly the source bytes."""
    assert roundtrip_hashes[key] == source_hash


@pytest.mark.parametrize("key", ["whole", "stream"])
def test_magic_header(results, key):
    assert results[key].output_path.read_bytes()[:2] == b"\x1f\x8b"


def test_decompression_via_stdlib(results, source_hash, tmp_path):
    """Independent check using plain gzip.decompress."""
    for key in ("whole", "stream"):
        blob = gzip.decompress(results[key].output_path.read_bytes())
        assert hashlib.sha256(blob).hexdigest() == source_hash


# ------------------------------------------------------------ round-trip

def test_both_hashes_match_source(roundtrip_hashes, source_hash):
    assert roundtrip_hashes["whole"] == source_hash
    assert roundtrip_hashes["stream"] == source_hash


# --------------------------------------------------------------- memory

def test_streaming_peak_under_3mb(source: Path, tmp_path):
    dst = tmp_path / "mem_stream.gz"

    def run():
        with open(source, "rb") as fin, gzip.open(dst, "wb", compresslevel=9) as fout:
            for chunk in iter(lambda: fin.read(gzip_bench.CHUNK_SIZE), b""):
                fout.write(chunk)

    peak = _measure_peak(run)
    assert dst.exists()
    # 3 MB headroom covers the 256 KB chunk, zlib internal buffers and I/O.
    assert peak < 3 * 1024 * 1024, f"streaming peak {peak} bytes >= 3MB"


def test_wholeblob_peak_exceeds_40mb(source: Path, tmp_path):
    dst = tmp_path / "mem_whole.gz"

    def run():
        data = source.read_bytes()
        dst.write_bytes(gzip.compress(data, compresslevel=9))

    peak = _measure_peak(run)
    assert dst.exists()
    assert peak > 40 * 1024 * 1024, f"whole-blob peak {peak} bytes <= 40MB"


# --------------------------------------------------------------- report

def test_report_written_and_mentions_byte_difference(tmp_path, monkeypatch):
    monkeypatch.chdir(tmp_path)
    gzip_bench.generate_source(size=1 * 1024 * 1024)
    src_hash = gzip_bench.sha256_of(gzip_bench.SOURCE_PATH)
    ms = [gzip_bench.compress_wholeblob(), gzip_bench.compress_streaming()]
    hashes = {}
    for i, m in enumerate(ms):
        out = tmp_path / f"r{i}.bin"
        gzip_bench.decompress_to(m.output_path, out)
        hashes[m.name] = hashlib.sha256(out.read_bytes()).hexdigest()

    report = gzip_bench.build_report(ms, src_hash, hashes, tmp_path / "gzip_report.md")
    text = report.read_text()
    assert "MTIME" in text
    assert "differ" in text.lower()
